import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

from test_config import BASELINE_YAML

from salam_workbench import facade
from salam_workbench.config import validate_gemm_config


class FacadeTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="salam-facade-test-")
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name) / "engine"
        self.bench = self.root / "benchmarks/sys_validation/gemm"
        (self.bench / "hw").mkdir(parents=True)
        (self.root / "configs/SALAM/generated").mkdir(parents=True)
        (self.root / "SALAM-Configurator").mkdir(parents=True)
        for stem in ("top", "gemm"):
            (self.bench / "hw" / (stem + ".c")).write_text(
                "void " + stem + "(void) {}\n"
            )
        (self.bench / "defines.h").write_text(
            "#define CHECK\n#define TYPE int\n#define ROW 8\n#define COL 8\n"
        )
        (self.bench / "config.yml").write_text(BASELINE_YAML)
        for path in facade.GENERATOR_SOURCES:
            (self.root / path).write_text("# synthetic source for mock generator\n")
        self.out = Path(self.temporary.name) / "evidence"
        self.python = mock.patch.object(facade, "PYTHON", sys.executable)
        self.python.start()
        self.addCleanup(self.python.stop)
        self.mutation = None

    def generate(self, argv, **kwargs):
        self.assertEqual(
            argv[1:5],
            [
                "SALAM-Configurator/systembuilder.py",
                "--sysName",
                "gemm",
                "--benchDir",
            ],
        )
        self.assertFalse(kwargs["shell"])
        self.assertEqual(kwargs["env"]["M5_PATH"], str(self.root))
        destination = Path(argv[argv.index("--output-dir") + 1])
        for relative, text in GENERATED_FIXTURES.items():
            # Fixture is an inspected real generated output with only the root token replaced.
            text = text.replace("__ENGINE_ROOT__", str(self.root).replace("\\", "/"))
            if self.mutation:
                text = self.mutation(relative, text)
            path = destination / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
        kwargs["stdout"].write(b"mock generator completed\n")
        return subprocess.CompletedProcess(argv, 0)

    def test_real_output_shape_and_snapshots(self):
        old = self.root / facade.GENERATED[0]
        old.write_text("# previous generated output\n")
        with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertTrue(result["valid"], result["errors"])
        self.assertEqual(result["state"], "generated")
        self.assertEqual(len(result["installed"]), 3)
        self.assertEqual(
            (self.out / "before" / facade.GENERATED[0]).read_text(),
            "# previous generated output\n",
        )
        devices = result["generated_validation"]["devices"]
        self.assertEqual(devices[1]["declared_payload_bytes"], 25)
        self.assertEqual(devices[1]["allocated_pio_bytes"], 64)
        self.assertEqual(devices[2]["declared_payload_bytes"], 1)
        self.assertEqual(devices[2]["allocated_pio_bytes"], 64)
        self.assertTrue((self.out / "facade.json").is_file())

    def test_missing_field_rejects_before_generator(self):
        path = self.bench / "config.yml"
        path.write_text(BASELINE_YAML.replace("      PIOSize: 25\n", ""))
        with mock.patch.object(facade.subprocess, "run") as launch:
            result = facade.validate_and_generate(self.root, self.out)
        launch.assert_not_called()
        self.assertFalse(result["valid"])
        self.assertIn("PIOSize", result["errors"][0])

    def test_generator_nonzero_retains_logs(self):
        def failed(argv, **kwargs):
            kwargs["stderr"].write(b"generation failed\n")
            return subprocess.CompletedProcess(argv, 7)

        with mock.patch.object(facade.subprocess, "run", side_effect=failed):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertEqual(result["command"]["return_code"], 7)
        self.assertEqual(result["installed"], [])
        self.assertEqual(
            (self.out / "generator.stderr.txt").read_text(),
            "generation failed\n",
        )

    def test_timeout_is_non_success(self):
        with mock.patch.object(
            facade.subprocess,
            "run",
            side_effect=subprocess.TimeoutExpired(["fixture"], 1),
        ):
            result = facade.validate_and_generate(
                self.root, self.out, timeout_seconds=1
            )
        self.assertFalse(result["valid"])
        self.assertEqual(result["state"], "timed_out")
        self.assertEqual(result["installed"], [])

    def test_malformed_generated_python_not_installed(self):
        self.mutation = (
            lambda path, text: "invalid syntax !!"
            if path.endswith("fs_gemm.py")
            else text
        )
        with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertEqual(result["installed"], [])
        self.assertIn("SyntaxError", result["errors"][0])

    def test_header_address_mismatch_not_installed(self):
        self.mutation = lambda path, text: text.replace(
            "#define GEMM 0x10020080", "#define GEMM 0x10020081"
        )
        with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertEqual(result["installed"], [])
        self.assertIn("generated header addresses", result["errors"][0])

    def test_actual_padded_pio_size_checked(self):
        self.mutation = lambda path, text: text.replace(
            "pio_addr=0x10020040, pio_size=64",
            "pio_addr=0x10020040, pio_size=25",
        )
        with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertEqual(result["installed"], [])
        self.assertIn("clstr.top", result["errors"][0])

    def test_duplicate_header_macro_rejected(self):
        self.mutation = (
            lambda path, text: text + "\n#define GEMM 0x10020080\n"
            if path.endswith(".h")
            else text
        )
        with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertIn("Duplicate generated header macro", result["errors"][0])

    def test_input_changed_by_generator_is_not_accepted(self):
        def changed(argv, **kwargs):
            process = self.generate(argv, **kwargs)
            with (self.bench / "config.yml").open("a") as handle:
                handle.write("\n# concurrently changed\n")
            return process

        with mock.patch.object(facade.subprocess, "run", side_effect=changed):
            result = facade.validate_and_generate(self.root, self.out)
        self.assertFalse(result["valid"])
        self.assertEqual(result["installed"], [])
        self.assertIn("input changed", result["errors"][0])

    def test_evidence_collision_preserves_previous_result(self):
        self.out.mkdir()
        previous = self.out / "facade.json"
        previous.write_text("previous evidence\n")
        with self.assertRaises(FileExistsError):
            facade.validate_and_generate(self.root, self.out)
        self.assertEqual(previous.read_text(), "previous evidence\n")

    def test_secret_environment_not_captured(self):
        with mock.patch.dict(
            facade.os.environ, {"WORKBENCH_SECRET_TEST": "not-for-log"}
        ):
            with mock.patch.object(facade.subprocess, "run", side_effect=self.generate):
                result = facade.validate_and_generate(self.root, self.out)
        self.assertTrue(result["valid"], result["errors"])
        self.assertNotIn("WORKBENCH_SECRET_TEST", result["command"]["environment"])
        self.assertNotIn("not-for-log", (self.out / "facade.json").read_text())


